def policy(obs,P):
    x=obs[0]
    v=obs[1]
    if x <= P['p_left']:
        return 1
    if x <= P['p_near']:
        if v <= P['v_thr']:
            return 0
        else:
            return 2
    if v > P['v_high']:
        return 2
    if v > P['v_mid_low'] and v <= P['v_mid_high'] and x > P['p_mid_neg']:
        return 0
    if x >= P['p_far']:
        return 2
    if x > P['p_pos']:
        if v < P['v_pos_neg']:
            return 2
        if v < P['v_pos_left_thr']:
            return 0
        return 2
    if x > P['p_mid']:
        if v < P['v_low_thr']:
            return 2
        if v < P['v_noop_high']:
            return 1
        return 0
    return 0
